import{_ as t,o,c as a,ao as i}from"./chunks/framework.DJNc2e_g.js";const u=JSON.parse('{"title":"Limitations","description":"","frontmatter":{},"headers":[],"relativePath":"limitations.md","filePath":"limitations.md","lastUpdated":null}'),d={name:"limitations.md"};function n(c,e,s,r,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="Limitations" tabindex="-1">Limitations <a class="header-anchor" href="#Limitations" aria-label="Permalink to &quot;Limitations {#Limitations}&quot;">​</a></h1><p>XML Schema is a large recommendation, and the packages implement the part of it that the schemas they were written for use. The list below is what is known not to work.</p><h2 id="Schema-features" tabindex="-1">Schema features <a class="header-anchor" href="#Schema-features" aria-label="Permalink to &quot;Schema features {#Schema-features}&quot;">​</a></h2><ul><li><p><code>xs:include</code>, <code>xs:import</code> and <code>xs:redefine</code> are not read: a schema has to be in one file.</p></li><li><p>A schema without a <code>targetNamespace</code> is not supported.</p></li><li><p><code>xs:list</code> is not read; an element that repeats, with <code>maxOccurs</code>, is. A union is read when its member types are written as nested <code>xs:simpleType</code> elements, not when they are named in <code>memberTypes</code>.</p></li><li><p>Attribute declarations do not become fields. The attributes of an element are kept as strings in its <code>__xml_attributes</code> dictionary.</p></li><li><p>Element and type names that are not valid Julia identifiers must be renamed with <code>mapping</code>; see <a href="./guide/renaming">Renaming elements and types</a>. Without it, the module is generated but cannot be included.</p></li></ul><h2 id="Built-in-types" tabindex="-1">Built-in types <a class="header-anchor" href="#Built-in-types" aria-label="Permalink to &quot;Built-in types {#Built-in-types}&quot;">​</a></h2><p>These built-in types are mapped to Julia types: <code>string</code>, <code>boolean</code>, <code>decimal</code> and <code>double</code> (<code>Float64</code>), <code>integer</code> and <code>int</code> (<code>Int64</code>), <code>nonNegativeInteger</code> and <code>positiveInteger</code> (<code>UInt64</code>), <code>dateTime</code>, <code>date</code>, <code>time</code> and <code>base64Binary</code>. Other built-in types, such as <code>float</code>, <code>long</code>, <code>token</code> or <code>anyURI</code>, are not.</p><p><code>decimal</code> is held as a <code>Float64</code>, so a decimal value with more significant digits than a <code>Float64</code> holds loses them, and trailing zeros are not kept when it is written back.</p><h2 id="Restrictions" tabindex="-1">Restrictions <a class="header-anchor" href="#Restrictions" aria-label="Permalink to &quot;Restrictions {#Restrictions}&quot;">​</a></h2><p>Only these facets are checked: <code>minInclusive</code>, <code>maxInclusive</code>, <code>minExclusive</code> and <code>maxExclusive</code> on numbers and <code>dateTime</code> values, and <code>totalDigits</code> and <code>fractionDigits</code> on numbers. The string facets <code>length</code>, <code>minLength</code>, <code>maxLength</code>, <code>pattern</code> and <code>enumeration</code> are not checked, so a document that violates them loads, and an object that violates them is written. A <code>dateTime</code> bound and value compare only when both have a zone offset or neither does; otherwise the check throws an <code>ArgumentError</code>, as XML Schema leaves their order undetermined.</p><h2 id="Times" tabindex="-1">Times <a class="header-anchor" href="#Times" aria-label="Permalink to &quot;Times {#Times}&quot;">​</a></h2><p>A <code>dateTime</code> with more than nine digits after the seconds is cut to nanoseconds, with a warning. The difference of two <code>DateTimeNs</code> values is in nanoseconds, which span about 292 years; a longer difference throws an <code>OverflowError</code>. Rounding below a millisecond takes only steps that divide it.</p>',11)])])}const p=t(d,[["render",n]]);export{u as __pageData,p as default};
